'use strict';
window.OrthodoxOffline=(()=>{
  let controller=null,manifest=null;
  async function catalog(){if(!manifest){const response=await fetch(window.OrthodoxSite?'/offline-manifest.json':'offline-manifest.json');if(!response.ok)throw new Error('Offline catalogue could not be loaded.');manifest=await response.json();}return manifest;}
  async function worker(){if(!('serviceWorker'in navigator))throw new Error('Offline reading is not supported by this browser.');await navigator.serviceWorker.register(window.OrthodoxSite?'/sw.js':'sw.js',{scope:window.OrthodoxSite?'/':'./'});const registration=await navigator.serviceWorker.ready;return registration.active;}
  async function command(type,pack,onProgress){const active=await worker();return new Promise((resolve,reject)=>{const channel=new MessageChannel();channel.port1.onmessage=event=>{const message=event.data;if(message.type==='progress')onProgress?.(message);else{channel.port1.close();message.ok?resolve(message):reject(new Error(message.error||'Offline operation failed.'));}};active.postMessage({type,pack},[channel.port2]);});}
  async function mount({root}){controller=new AbortController();root.innerHTML='<h1>Offline reading</h1><p>Loading collections…</p>';try{const data=await catalog();if(!root.isConnected)return;root.innerHTML='<h1>Offline reading</h1><p>Download published reading collections for use without a network connection. External readings and recordings still require internet. Account synchronization waits until you reconnect.</p><section class="setting-panel offline-packs"><h2>Reading collections</h2>'+data.packs.map(p=>`<label><input type="checkbox" name="offline-pack" value="${p.id}" ${p.id==='readings'?'checked':''}><span><strong>${p.label}</strong><br>${p.description} · ${p.files.length} files · approximately ${(p.bytes/1048576).toFixed(1)} MB</span></label>`).join('')+'<div class="tool-actions"><button id="download-offline" class="primary">Download selected collections</button><button id="remove-offline" class="secondary">Remove offline downloads</button></div><p id="offline-status" class="offline-status" role="status"></p></section><p>Downloads contain public reading material only. Notes and account sessions are not stored in the offline content cache. Browser storage may be cleared by the browser; keep a separate progress backup.</p><p><a href="#/settings">Export progress and notes</a></p>';const status=root.querySelector('#offline-status');const stored=await caches.keys();status.textContent=stored.some(k=>k.startsWith('orthodox-way-offline-'))?'Offline collections are present. Download again after an app update to refresh them.':'No offline collections downloaded.';
      root.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button)return;if(!['download-offline','remove-offline'].includes(button.id))return;root.querySelectorAll('button').forEach(b=>b.disabled=true);try{if(button.id==='remove-offline'){await command('remove');status.textContent='Offline downloads removed. Your notes and progress remain.';}else{const selected=[...root.querySelectorAll('[name=offline-pack]:checked')].map(el=>el.value);if(!selected.includes('readings'))selected.unshift('readings');for(const pack of selected){const info=data.packs.find(p=>p.id===pack);await command('download',pack,message=>status.textContent=info.label+': '+message.completed+' / '+message.total+' files');}status.textContent='Selected collections downloaded. You can close and reopen the app offline in this browser.';}}catch(error){status.textContent=error.message;}finally{root.querySelectorAll('button').forEach(b=>b.disabled=false);}},{signal:controller.signal});
    }catch(error){if(root.isConnected)root.innerHTML='<h1>Offline reading</h1><p role="alert">'+error.message.replace(/[<>&]/g,'')+'</p><button id="retry-offline">Retry</button>';root.querySelector('#retry-offline')?.addEventListener('click',()=>mount({root}));}}
  function unmount(){controller?.abort();controller=null;}
  return {mount,unmount,catalog,command};
})();
